CREATE TABLE IF NOT EXISTS commerce_prices(sku text NOT NULL,cycle text NOT NULL CHECK(cycle IN('once','monthly','quarterly','semiannual','yearly')),amount numeric(12,2) CHECK(amount>=0),active boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(sku,cycle));
CREATE TABLE IF NOT EXISTS commerce_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text UNIQUE NOT NULL,secret_hash text NOT NULL,idempotency_key uuid NOT NULL UNIQUE,name text NOT NULL,email text NOT NULL,phone text NOT NULL,company text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',payment_method text NOT NULL CHECK(payment_method IN('gateway','bank','quote')),status text NOT NULL DEFAULT 'new' CHECK(status IN('new','awaiting_payment','awaiting_transfer','quoted','paid','failed','cancelled','fulfilled')),subtotal_halalas bigint,vat_halalas bigint,total_halalas bigint,currency text NOT NULL DEFAULT 'SAR',invoice_id text UNIQUE,checkout_url text,created_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz);
CREATE TABLE IF NOT EXISTS commerce_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES commerce_orders(id) ON DELETE CASCADE,sku text NOT NULL,cycle text NOT NULL,quantity int NOT NULL,unit_halalas bigint,configuration jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS commerce_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES commerce_orders(id),sku text NOT NULL,cycle text NOT NULL,status text NOT NULL DEFAULT 'active',starts_at timestamptz NOT NULL DEFAULT now(),renews_at timestamptz,UNIQUE(order_id,sku,cycle));
CREATE TABLE IF NOT EXISTS commerce_modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text UNIQUE NOT NULL,slug text UNIQUE NOT NULL,name_ar text NOT NULL,name_en text NOT NULL,description_ar text NOT NULL DEFAULT '',odoo_versions text[] NOT NULL DEFAULT '{}',licence text NOT NULL DEFAULT 'Proprietary',version text NOT NULL DEFAULT '1.0.0',r2_key text,sha256 text,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_payment_events(invoice_id text NOT NULL,status text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(invoice_id,status));
CREATE INDEX IF NOT EXISTS commerce_order_created ON commerce_orders(created_at DESC);
CREATE INDEX IF NOT EXISTS commerce_order_email ON commerce_orders(lower(email));
INSERT INTO commerce_prices(sku,cycle,amount,active) SELECT p.sku,c.cycle,NULL,false FROM (VALUES('MIF-ERP'),('MIF-CONTROL'),('MIF-PARTNERS'),('MIF-MARKETING'),('MIF-HOSTING'),('MIF-EMAIL'))p(sku) CROSS JOIN (VALUES('once'),('monthly'),('quarterly'),('semiannual'),('yearly'))c(cycle) ON CONFLICT DO NOTHING;
